class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (typeof capacity !== 'number' || !isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = now;

    // Başlangıçta kova dolu
    this.tokens = capacity;
    this.lastRefillTime = now();
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || !isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    const timeNow = this.now();
    this._refill(timeNow);

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    const timeNow = this.now();
    this._refill(timeNow);
    return this.tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || !isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    // capacity veya refillPerSecond sıfır ise
    if (this.capacity === 0 || this.refillPerSecond === 0) {
      return Infinity;
    }

    const timeNow = this.now();
    this._refill(timeNow);

    if (this.tokens >= n) {
      return 0;
    }

    // Kalan jeton miktarı
    const remainingTokens = n - this.tokens;

    // Her saniyede refillPerSecond kadar jeton geliyor.
    // Bu yüzden kalan süre: remainingTokens / refillPerSecond * 1000 ms

    const secondsUntil = remainingTokens / this.refillPerSecond;
    return Math.ceil(secondsUntil * 1000); // Milisaniye cinsinden yukarı yuvarlanır
  }

  _refill(timeNow) {
    if (timeNow <= this.lastRefillTime) {
      // Saat geri gidiyor ya da aynı an, hiçbir şey yapma
      return;
    }

    const elapsedSeconds = (timeNow - this.lastRefillTime) / 1000; 
    const refillAmount = elapsedSeconds * this.refillPerSecond;

    if (refillAmount > 0) {
      // Jetonları kova dolana kadar doldur
      this.tokens = Math.min(this.capacity, this.tokens + refillAmount);
    }

    this.lastRefillTime = timeNow;
  }
}

module.exports = { TokenBucket };

