import os

# node.js ile çalıştırabilmek için bir test scripti oluşturuyoruz.
test_code = """
const { TokenBucket } = require('./kova');

// Test 1: Basit kullanım
console.log('Test 1: Basit kullanım');
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log('Available tokens:', bucket.available());
console.log('Try take 3:', bucket.tryTake(3)); // true olmalı
console.log('Available after take:', bucket.available());

// Test 2: msUntil testi
console.log('\\nTest 2: msUntil');
console.log('ms until 5:', bucket.msUntil(5));
console.log('ms until 15 (yeterli değil):', bucket.msUntil(15));

// Test 3: Geçersiz değerler
console.log('\\nTest 3: Geçersiz değerler');
try {
    new TokenBucket({ capacity: -1, refillPerSecond: 2 });
} catch(e) {
    console.log('Capacity negatif hata:', e.message);
}

// Test 4: Saat geri giderse
console.log('\\nTest 4: Saat geri gidiyor');
const fakeNow = () => 1000;
const bucket2 = new TokenBucket({ capacity: 5, refillPerSecond: 1, now: fakeNow });
bucket2.lastRefillTime = 500; // Geriye dönük zaman
console.log('Tokens after refill:', bucket2.available());
"""

with open("test.js", "w") as f:
    f.write(test_code)

# Node.js ile çalıştır
result = os.system("node test.js")
print("Test sonucu:", result)

# TokenBucket sınıfını doğrudan Python ile kullanabilmek için, JavaScript kodunu bir dosyaya kaydedip onu çalıştıracağız.
# Ancak bu ortamda sadece Node.js ve Python komutları çalışır.

# Önce kova.js dosyasının içeriğini kontrol et
import os

# Dosya var mı?
if os.path.exists('kova.js'):
    print("kova.js dosyası mevcut.")

    # Dosyanın içeriğini oku
    with open('kova.js', 'r') as f:
        content = f.read()

    # Test için küçük bir JS betiği yazalım
    test_script = '''
const { TokenBucket } = require('./kova');

// Temel kullanım
console.log("Test 1: Basit kullanım");
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log("Available tokens:", bucket.available());
console.log("Try take 3:", bucket.tryTake(3)); // true olmalı
console.log("Available after take:", bucket.available());

// msUntil testi
console.log("\\nTest 2: msUntil");
console.log("ms until 5:", bucket.msUntil(5));
console.log("ms until 15 (yeterli değil):", bucket.msUntil(15));

// Geçersiz değerler
console.log("\\nTest 3: Geçersiz değerler");
try {
    new TokenBucket({ capacity: -1, refillPerSecond: 2 });
} catch(e) {
    console.log("Capacity negatif hata:", e.message);
}

// Saat geri giderse testi
console.log("\\nTest 4: Saat geri gidiyor");
const fakeNow = () => 1000;
const bucket2 = new TokenBucket({ capacity: 5, refillPerSecond: 1, now: fakeNow });
bucket2.lastRefillTime = 500; // Geriye dönük zaman
console.log("Tokens after refill:", bucket2.available());

// Yeni bir test: sıfır refill
console.log("\\nTest 5: Sıfır refill");
const zeroBucket = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
console.log("msUntil(1) with zero refill:", zeroBucket.msUntil(1));
'''

    # Test scriptini kaydet
    with open('test_runner.js', 'w') as f:
        f.write(test_script)

    print("Test komutu hazırlanıyor...")
    print("Komut: node test_runner.js")
else:
    print("kova.js dosyası bulunamadı.")

